cat <<'EOF' > src/main.rs
use clap::Parser;
use is_terminal::IsTerminal;
use std::fs::File;
use std::io::{self, Read};

#[derive(Parser, Debug)]
#[command(name = "hx", version = "0.7.0", about = "Futuristic take on hexdump, made in Rust.")]
struct Args {
    #[arg(value_name = "INPUTFILE")]
    input_file: Option<String>,

    #[arg(short = 'c', long, default_value_t = 10, help = "Set column length")]
    cols: usize,

    #[arg(short = 'l', long, help = "Set <len> bytes to read")]
    len: Option<usize>,

    #[arg(short = 'f', long, value_name = "format", help = "Set format of octet: Octal (o), LowerHex (x), UpperHex (X), Binary (b)")]
    format: Option<String>,

    #[arg(short = 't', long, value_name = "color", help = "Set color tint terminal output. 0 to disable, 1 to enable")]
    color: Option<u8>,

    #[arg(short = 'a', long, value_name = "array_format", help = "Set source code format output: rust (r), C (c), golang (g), python (p), kotlin (k), java (j), swift (s), fsharp (f)")]
    array: Option<char>,

    #[arg(short = 'u', long, value_name = "func_length", help = "Set function wave length")]
    func: Option<usize>,

    #[arg(short = 'p', long, default_value_t = 4, value_name = "func_places", help = "Set function wave output decimal places")]
    places: usize,

    #[arg(short = 'r', long, value_name = "prefix", help = "Include prefix in output (e.g. 0x/0b/0o). 0 to disable, 1 to enable")]
    prefix: Option<u8>,
}

fn main() -> io::Result<()> {
    let args = Args::parse();

    if let Some(func_len) = args.func {
        for i in 0..func_len {
            let val = (i as f64 * std::f64::consts::PI / (2.0 * func_len as f64)).sin();
            print!("{:.*},", args.places, val);
            if (i + 1) % 10 == 0 || i + 1 == func_len {
                println!();
            }
        }
        return Ok(());
    }

    let mut input: Box<dyn Read> = match args.input_file {
        Some(ref path) => Box::new(File::open(path).map_err(|e| {
            eprintln!("error: {} (os error {})", e, e.raw_os_error().unwrap_or(0));
            std::process::exit(1);
        })?),
        None => Box::new(io::stdin()),
    };

    let mut buffer = Vec::new();
    if let Some(len) = args.len {
        input.take(len as u64).read_to_end(&mut buffer)?;
    } else {
        input.read_to_end(&mut buffer)?;
    }

    if let Some(array_format) = args.array {
        print_array(&buffer, array_format, args.cols);
    } else {
        print_hexdump(&buffer, &args);
    }

    Ok(())
}

fn print_array(buffer: &[u8], format: char, cols: usize) {
    let len = buffer.len();
    match format {
        'r' => println!("let ARRAY: [u8; {}] = [", len),
        'c' => println!("unsigned char ARRAY[{}] = {{", len),
        'g' => println!("a := [{}]byte{{", len),
        'p' => println!("a = ["),
        'k' => println!("val a = byteArrayOf("),
        'j' => println!("byte[] a = new byte[]{{"),
        's' => println!("let a: [UInt8] = ["),
        'f' => println!("let a = [|"),
        _ => {}
    }

    for (i, chunk) in buffer.chunks(cols).enumerate() {
        print!("    ");
        for (j, &b) in chunk.iter().enumerate() {
            match format {
                'f' => print!("0x{:02x}uy", b),
                _ => print!("0x{:02x}", b),
            }
            if i * cols + j < len - 1 {
                if format == 'f' {
                    print!("; ");
                } else {
                    print!(", ");
                }
            } else if format == 'g' {
                print!(", ");
            }
        }
        println!();
    }

    if buffer.len() > 0 && buffer.len() % cols == 0 {
        println!();
    }

    match format {
        'r' => println!("];"),
        'c' => println!("}};"),
        'g' => println!("}}"),
        'p' => println!("]"),
        'k' => println!(")"),
        'j' => println!("}};"),
        's' => println!("]"),
        'f' => println!("|]"),
        _ => {}
    }
}

fn print_hexdump(buffer: &[u8], args: &Args) {
    let use_color = match args.color {
        Some(1) => true,
        Some(0) => false,
        _ => {
            if std::env::var("NO_COLOR").is_ok() {
                false
            } else {
                io::stdout().is_terminal()
            }
        }
    };

    let prefix = args.prefix.unwrap_or(1) == 1;
    let format_char = args.format.as_deref().unwrap_or("x");

    let mut i = 0;
    loop {
        if i >= buffer.len() && i > 0 {
            break;
        }
        let chunk_size = std::cmp::min(args.cols, if buffer.len() > i { buffer.len() - i } else { 0 });
        let chunk = &buffer[i..i+chunk_size];

        print!("0x{:06x}: ", i);

        for j in 0..args.cols {
            if j < chunk_size {
                let b = chunk[j];
                if use_color {
                    print!("\x1b[38;5;{}m", b);
                }
                match format_char {
                    "o" => {
                        if prefix { print!("0o"); }
                        print!("{:04o}", b);
                    }
                    "X" => {
                        if prefix { print!("0x"); }
                        print!("{:02X}", b);
                    }
                    "b" => {
                        if prefix { print!("0b"); }
                        print!("{:08b}", b);
                    }
                    _ => {
                        if prefix { print!("0x"); }
                        print!("{:02x}", b);
                    }
                }
                if use_color {
                    print!("\x1b[0m");
                }
                print!(" ");
            } else {
                // padding
                // My formula was: (cols - bytes_in_line) * 5 + 1
                // Wait, if I do it per column:
                // Actually, I can just print the spaces needed.
                // But the total number of spaces after the last byte is what matters.
                break;
            }
        }

        // Padding to reach the ASCII part
        let remaining_cols = args.cols - chunk_size;
        for _ in 0..remaining_cols * 5 {
            print!(" ");
        }
        print!(" "); // The +1 space

        for j in 0..chunk_size {
            let b = chunk[j];
            if use_color {
                print!("\x1b[38;5;{}m", b);
            }
            if b >= 32 && b <= 126 {
                print!("{}", b as char);
            } else {
                print!(".");
            }
            if use_color {
                print!("\x1b[0m");
            }
        }
        println!();

        if buffer.len() == 0 {
            break;
        }
        i += args.cols;
    }

    println!("   bytes: {}", buffer.len());
}
EOF
"}

