        color: None,
        array: None,
        func: None,
        places: 4,
        prefix: true,
    };

    while let Some(arg) = args_iter.next() {
        match arg.as_str() {
            "-h" | "--help" => {
                print_help();
                return Ok(());
            }
            "-V" | "--version" => {
                println!("hx 0.7.0");
                return Ok(());
            }
            "-c" | "--cols" => {
                if let Some(val) = args_iter.next() {
                    args.cols = val.parse().unwrap_or(10);
                }
            }
            "-l" | "--len" => {
                if let Some(val) = args_iter.next() {
                    args.len = Some(val.parse().unwrap_or(0));
                }
            }
            "-f" | "--format" => {
                if let Some(val) = args_iter.next() {
                    args.format = val;
                }
            }
            "-t" | "--color" => {
                if let Some(val) = args_iter.next() {
                    args.color = Some(val == "1");
                }
            }
            "-a" | "--array" => {
                if let Some(val) = args_iter.next() {
                    args.array = val.chars().next();
                }
            }
            "-u" | "--func" => {
                if let Some(val) = args_iter.next() {
                    args.func = Some(val.parse().unwrap_or(0));
                }
            }
            "-p" | "--places" => {
                if let Some(val) = args_iter.next() {
                    args.places = val.parse().unwrap_or(4);
                }
            }
            "-r" | "--prefix" => {
                if let Some(val) = args_iter.next() {
                    args.prefix = val == "1";
                }
            }
            _ if arg.starts_with('-') => {
            }
            _ => {
                if args.input_file.is_none() {
                    args.input_file = Some(arg);
                } else {
                    eprintln!("error: unexpected argument '{}' found", arg);
                    println!("");
                    println!("Usage: executable [OPTIONS] [INPUTFILE]");
                    println!("");
                    println!("For more information, try '--help'.");
                    std::process::exit(2);
                }
            }
        }
    }

    if let Some(func_len) = args.func {
        for i in 0..func_len {
            let val = (i as f64 * std::f64::consts::PI / (2.0 * func_len as f64)).sin();
            print!("{:.*},", args.places, val);
            if (i + 1) % 10 == 0 || i + 1 == func_len {
                println!();
            }
        }
        return Ok(());
    }

    let mut input: Box<dyn Read> = match args.input_file {
        Some(ref path) => match File::open(path) {
            Ok(file) => Box::new(file),
            Err(e) => {
                eprintln!("error: {} (os error {})", e, e.raw_os_error().unwrap_or(0));
                std::process::exit(1);
            }
        },
        None => Box::new(io::stdin()),
    };

    let mut buffer = Vec::new();
    if let Some(len) = args.len {
        input.take(len as u64).read_to_end(&mut buffer)?;
    } else {
        input.read_to_end(&mut buffer)?;
    }

    if let Some(array_format) = args.array {
        print_array(&buffer, array_format, args.cols);
    } else {
        print_hexdump(&buffer, &args);
    }

    Ok(())
}

fn print_array(buffer: &[u8], format: char, cols: usize) {
    let len = buffer.len();
    match format {
        'r' => println!("let ARRAY: [u8; {}] = [", len),
        'c' => println!("unsigned char ARRAY[{}] = {{", len),
        'g' => println!("a := [{}]byte{{", len),
        'p' => println!("a = ["),
        'k' => println!("val a = byteArrayOf("),
        'j' => println!("byte[] a = new byte[]{{"),
        's' => println!("let a: [UInt8] = ["),
        'f' => println!("let a = [|"),
        _ => {}
    }

    for (i, chunk) in buffer.chunks(cols).enumerate() {
        print!("    ");
        for (j, &b) in chunk.iter().enumerate() {
            match format {
                'f' => print!("0x{:02x}uy", b),
                _ => print!("0x{:02x}", b),
            }
            if i * cols + j < len - 1 {
                if format == 'f' {
                    print!("; ");
                } else {
                    print!(", ");
                }
            } else if format == 'g' {
                print!(", ");
            }
        }
        println!();
    }

    if buffer.len() % cols == 0 {
        println!("    ");
    }

    match format {
        'r' => println!("];"),
        'c' => println!("}};"),
        'g' => println!("}}"),
        'p' => println!("]"),
        'k' => println!(")"),
        'j' => println!("}};"),
        's' => println!("]"),
        'f' => println!("|]"),
        _ => {}
    }
}

fn print_hexdump(buffer: &[u8], args: &Args) {
    let use_color = match args.color {
        Some(b) => b,
        None => {
            if env::var("NO_COLOR").is_ok() {
                false
            } else {
                io::stdout().is_terminal()
            }
        }
    };

    let prefix = args.prefix;
    let format_char = &args.format;
    let cols = args.cols;

    let mut i = 0;
    loop {
        let chunk_size = std::cmp::min(cols, if buffer.len() > i { buffer.len() - i } else { 0 });
        let chunk = &buffer[i..i+chunk_size];

        print!("0x{:06x}: ", i);

        for j in 0..cols {
            if j < chunk_size {
                let b = chunk[j];
                if use_color {
                    print!("\x1b[38;5;{}m", b);
                }
                match format_char.as_str() {
                    "o" => {
                        if prefix { print!("0o"); }
                        print!("{:04o}", b);
                    }
                    "X" => {
                        if prefix { print!("0x"); }
                        print!("{:02X}", b);
                    }
                    "b" => {
                        if prefix { print!("0b"); }
                        print!("{:08b}", b);
                    }
                    _ => {
                        if prefix { print!("0x"); }
                        print!("{:02x}", b);
                    }
                }
                if use_color {
                    print!("\x1b[0m");
                }
                print!(" ");
            }
        }

        // Padding to reach the ASCII part
        let remaining_cols = cols - chunk_size;
        for _ in 0..remaining_cols * 5 {
            print!(" ");
        }

        for j in 0..chunk_size {
            let b = chunk[j];
            if use_color {
                print!("\x1b[38;5;{}m", b);
            }
            if b >= 32 && b <= 126 {
                print!("{}", b as char);
            } else {
                print!(".");
            }
            if use_color {
                print!("\x1b[0m");
            }
        }
        println!();

        i += cols;
        if i > buffer.len() {
            break;
        }
    }

    println!("   bytes: {}", buffer.len());
}
